window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-36c7987df29d9187"]={"versions": [{"id": "FIG-36c7987df29d9187", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb des AUTOSAR E2E-Profils 7 (<code>E2E_P07Protect()</code>). Das Diagramm beschreibt die serialisierende Einfügung der Datenkennung (Data ID) in den zu schützenden Nutzdaten-Puffer auf Protokollebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Funktion</strong>: <code>E2E_P07Protect()</code>\n</li><li><strong>Eingangsdaten / Konfiguration</strong>: <code>Config-&gt;DataID</code> (4 Byte Datenkennung)\n</li><li><strong>Zielpuffer</strong>: Byte-Array <code>Data[]</code>\n</li><li><strong>Adressierung / Offset</strong>: <code>Data[Offset+16...Offset+19]</code> (4 aufeinanderfolgende Bytes ab relativem Byte-Offset +16)\n</li><li><strong>Formatierung</strong>: Big-Endian-Byte-Reihenfolge (Network Byte Order)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten (<code>InitialNode</code>).\n</li><li>Übergang zum Aktionsknoten: „Copy 4-byte Config-&gt;DataID to bytes Data[Offset+16...Offset+19] in Big Endian order“.\n</li><li>Übergang zum Endknoten (<code>ActivityFinalNode</code>) und Abschluss des Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich gemäß AUTOSAR-Spezifikationsanforderung <code>PRS_E2E_00491</code> für das E2E-Profil 7. Entwickler müssen gewährleisten, dass der 32-Bit-Wert <code>DataID</code> aus der Konfigurationsstruktur exakt in Big-Endian-Reihenfolge an den Byte-Positionen 16 bis 19 relativ zu <code>Offset</code> in das Nutzdatenarray geschrieben wird. Ein Pufferüberlauf ist durch vorangehende Längenprüfungen auszuschließen.</p>"}, {"id": "FIG-1047daa2880d054a", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts innerhalb des AUTOSAR E2E-Profils 7 (<code>E2E_P07Protect()</code>). Das Diagramm beschreibt die serialisierende Einfügung der Datenkennung (Data ID) in den zu schützenden Nutzdaten-Puffer auf Protokollebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext / Funktion</strong>: <code>E2E_P07Protect()</code>\n</li><li><strong>Eingangsdaten / Konfiguration</strong>: <code>Config-&gt;DataID</code> (4 Byte Datenkennung)\n</li><li><strong>Zielpuffer</strong>: Byte-Array <code>Data[]</code>\n</li><li><strong>Adressierung / Offset</strong>: <code>Data[Offset+16...Offset+19]</code> (4 aufeinanderfolgende Bytes ab relativem Byte-Offset +16)\n</li><li><strong>Formatierung</strong>: Big-Endian-Byte-Reihenfolge (Network Byte Order)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten (<code>InitialNode</code>).\n</li><li>Übergang zum Aktionsknoten: „Copy 4-byte Config-&gt;DataID to bytes Data[Offset+16...Offset+19] in Big Endian order“.\n</li><li>Übergang zum Endknoten (<code>ActivityFinalNode</code>) und Abschluss des Teilschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich gemäß AUTOSAR-Spezifikationsanforderung <code>PRS_E2E_00491</code> für das E2E-Profil 7. Entwickler müssen gewährleisten, dass der 32-Bit-Wert <code>DataID</code> aus der Konfigurationsstruktur exakt in Big-Endian-Reihenfolge an den Byte-Positionen 16 bis 19 relativ zu <code>Offset</code> in das Nutzdatenarray geschrieben wird. Ein Pufferüberlauf ist durch vorangehende Längenprüfungen auszuschließen.</p>"}], "trans": [{"from": "FIG-36c7987df29d9187", "to": "FIG-1047daa2880d054a", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
